content:
:root {
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #eef2ff;
  --success: #10b981;
  --danger: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fef2f2;
  --bg-gradient-start: #f1f5f9;
  --bg-gradient-end: #e2e8f0;
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-subtle: #94a3b8;
  --border-color: #e2e8f0;
  --border-focus: #818cf8;
  --focus-outline: #4f46e5;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  color: var(--text-main);
  background: linear-gradient(135deg, var(--bg-gradient-start) 0%, var(--bg-gradient-end) 100%);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 2rem 1rem;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* 全体コンテナ */
.todo-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
}

/* メインカード */
.todo-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 2rem;
  border: 1px solid var(--border-color);
}

/* ヘッダー */
.todo-header {
  margin-bottom: 1.5rem;
  text-align: center;
}

.todo-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  margin-bottom: 0.35rem;
}

.todo-subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* 進捗バー */
.progress-container {
  background-color: #f8fafc;
  border-radius: var(--radius-md);
  padding: 0.875rem 1rem;
  margin-bottom: 1.5rem;
  border: 1px solid var(--border-color);
  position: relative;
}

.progress-bar-bg {
  width: 100%;
  height: 8px;
  background-color: #cbd5e1;
  border-radius: 9999px;
  overflow: hidden;
  margin-bottom: 0.5rem;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.1);
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #6366f1 0%, #10b981 100%);
  border-radius: 9999px;
  transition: width 0.35s ease;
  min-width: 0;
}

.progress-text {
  font-size: 0.8125rem;
  color: var(--text-muted);
  font-weight: 500;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* 新規タスクフォーム */
.todo-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.todo-input {
  flex: 1;
  padding: 0.75rem 1rem;
  font-size: 0.95rem;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: #ffffff;
  color: var(--text-main);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  outline: none;
}

.todo-input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}

.todo-input:focus-visible {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.25);
  outline: none;
}

.todo-input::placeholder {
  color: var(--text-subtle);
}

.add-button {
  background-color: var(--primary);
  color: #ffffff;
  font-weight: 600;
  font-size: 0.95rem;
  border: none;
  border-radius: var(--radius-md);
  padding: 0 1.25rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  white-space: nowrap;
  transition: background-color 0.15s ease, transform 0.05s ease, opacity 0.15s ease, box-shadow 0.15s ease;
  outline: none;
}

.add-button:hover:not(:disabled) {
  background-color: var(--primary-hover);
}

.add-button:active:not(:disabled) {
  transform: scale(0.98);
}

.add-button:focus-visible {
  outline: 2px solid var(--focus-outline);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.25);
}

.add-button:disabled {
  background-color: #94a3b8;
  color: #f1f5f9;
  cursor: not-allowed;
  opacity: 0.7;
  transform: none;
}

/* フィルタータブ */
.filter-tabs {
  display: flex;
  gap: 0.375rem;
  background-color: #f1f5f9;
  padding: 0.3rem;
  border-radius: var(--radius-md);
  margin-bottom: 1.25rem;
}

.filter-button {
  flex: 1;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
  text-align: center;
  outline: none;
}

.filter-button:hover {
  color: var(--text-main);
}

.filter-button:focus-visible {
  outline: 2px solid var(--focus-outline);
  outline-offset: 1px;
}

.filter-button-active {
  background-color: #ffffff;
  color: var(--primary);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* タスクリスト */
.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  margin-bottom: 1.5rem;
}

/* タスクアイテム */
.task-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: background-color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}

.task-item:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-sm);
}

.task-item-completed {
  background-color: #f8fafc;
  border-color: #e2e8f0;
}

.task-item-completed .task-title {
  color: var(--text-subtle);
  text-decoration: line-through;
}

.task-checkbox-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex: 1;
  min-width: 0;
  cursor: pointer;
  user-select: none;
}

.task-checkbox {
  width: 1.2rem;
  height: 1.2rem;
  accent-color: var(--primary);
  cursor: pointer;
  flex-shrink: 0;
  border-radius: 4px;
  outline: none;
}

.task-checkbox:focus-visible {
  outline: 2px solid var(--focus-outline);
  outline-offset: 2px;
}

.task-title {
  font-size: 0.95rem;
  color: var(--text-main);
  word-break: break-word;
  font-weight: 400;
}

.task-date {
  font-size: 0.75rem;
  color: var(--text-muted);
  background-color: #f1f5f9;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-sm);
  white-space: nowrap;
  margin: 0 0.5rem;
  flex-shrink: 0;
}

.delete-button {
  background: transparent;
  border: none;
  color: var(--text-subtle);
  padding: 0.35rem 0.5rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 0.85rem;
  transition: color 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  outline: none;
}

.delete-button:hover {
  color: var(--danger);
  background-color: var(--danger-light);
}

.delete-button:focus-visible {
  outline: 2px solid var(--danger);
  outline-offset: 2px;
}

/* 空状態 */
.empty-state {
  text-align: center;
  padding: 2.5rem 1rem;
  color: var(--text-muted);
  font-size: 0.925rem;
  background-color: #f8fafc;
  border-radius: var(--radius-md);
  border: 1px dashed var(--border-color);
  margin-bottom: 1.5rem;
}

/* フッター統計と一括削除 */
.stats-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 1rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.85rem;
  color: var(--text-muted);
  flex-wrap: wrap;
  gap: 0.75rem;
}

.clear-completed-button {
  background: transparent;
  border: none;
  color: var(--danger);
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.35rem 0.65rem;
  border-radius: var(--radius-sm);
  transition: background-color 0.15s ease, color 0.15s ease, opacity 0.15s ease;
  outline: none;
}

.clear-completed-button:hover:not(:disabled) {
  background-color: var(--danger-light);
  color: var(--danger-hover);
}

.clear-completed-button:focus-visible {
  outline: 2px solid var(--danger);
  outline-offset: 2px;
}

.clear-completed-button:disabled {
  color: var(--text-subtle);
  cursor: not-allowed;
  background-color: transparent;
  opacity: 0.6;
}

/* レスポンシブ対応 */
@media (max-width: 480px) {
  body {
    padding: 1rem 0.5rem;
  }

  .todo-card {
    padding: 1.25rem 1rem;
    border-radius: var(--radius-md);
  }

  .todo-title {
    font-size: 1.4rem;
  }

  .todo-form {
    flex-direction: column;
  }

  .add-button {
    padding: 0.75rem 1rem;
    width: 100%;
  }

  .task-item {
    padding: 0.65rem 0.75rem;
  }

  .task-date {
    display: none;
  }

  .stats-footer {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }

  .clear-completed-button {
    width: 100%;
    padding: 0.5rem;
  }
}

/**
 * ドメインモデル定義
 */
export interface TodoTask {
  id: string;
  title: string;
  isCompleted: boolean;
  /** 作成日時（ISO 8601形式文字列） */
  createdAt: string;
}

export type FilterStatus = 'all' | 'active' | 'completed';

/**
 * TaskItem コンポーネント固有 Props 定義
 */
export interface TaskItemProps {
  task: TodoTask;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

import { TaskItemProps } from '../types';

const TaskItem = ({ task, onToggle, onDelete }: TaskItemProps) => {
  const itemClassName = task.isCompleted
    ? 'task-item task-item-completed'
    : 'task-item';
  const checkboxId = `task-${task.id}`;

  return (
    <li className={itemClassName}>
      <label className="task-checkbox-label" htmlFor={checkboxId}>
        <input
          type="checkbox"
          id={checkboxId}
          className="task-checkbox"
          checked={task.isCompleted}
          onChange={() => onToggle(task.id)}
        />
        <span className="task-title">{task.title}</span>
      </label>
      <span className="task-date">{task.createdAt}</span>
      <button
        type="button"
        className="delete-button"
        onClick={() => onDelete(task.id)}
        aria-label={`タスク「${task.title}」を削除`}
        title="削除"
      >
        削除
      </button>
    </li>
  );
};

export default TaskItem;

import { useState } from 'react';
import { TodoTask, FilterStatus } from './types';
import TaskItem from './components/TaskItem';

const INITIAL_TASKS: TodoTask[] = [
  {
    id: '1',
    title: '夕食の食材の買い出し（野菜・牛乳）',
    isCompleted: false,
    createdAt: '今日 10:15',
  },
  {
    id: '2',
    title: '取引先への週次報告メールの返信',
    isCompleted: true,
    createdAt: '今日 09:30',
  },
  {
    id: '3',
    title: '来期プロジェクト企画資料の作成',
    isCompleted: false,
    createdAt: '昨日 17:00',
  },
  {
    id: '4',
    title: '軽いジョギングとストレッチ（30分）',
    isCompleted: true,
    createdAt: '昨日 19:45',
  },
];

const App = () => {
  const [tasks, setTasks] = useState<TodoTask[]>(INITIAL_TASKS);
  const [inputTitle, setInputTitle] = useState('');
  const [filter, setFilter] = useState<FilterStatus>('all');

  const totalCount = tasks.length;
  const completedCount = tasks.filter((t) => t.isCompleted).length;
  const activeCount = totalCount - completedCount;
  const progressPercent = totalCount === 0 ? 0 : Math.round((completedCount / totalCount) * 100);

  const handleAddTask = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = inputTitle.trim();
    if (!trimmed) return;

    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const createdAtStr = `今日 ${hours}:${minutes}`;

    const newTask: TodoTask = {
      id: crypto.randomUUID(),
      title: trimmed,
      isCompleted: false,
      createdAt: createdAtStr,
    };

    setTasks([newTask, ...tasks]);
    setInputTitle('');
  };

  const handleToggle = (id: string) => {
    setTasks(
      tasks.map((task) =>
        task.id === id ? { ...task, isCompleted: !task.isCompleted } : task
      )
    );
  };

  const handleDelete = (id: string) => {
    setTasks(tasks.filter((task) => task.id !== id));
  };

  const handleClearCompleted = () => {
    setTasks(tasks.filter((task) => !task.isCompleted));
  };

  const filteredTasks = tasks.filter((task) => {
    if (filter === 'active') return !task.isCompleted;
    if (filter === 'completed') return task.isCompleted;
    return true;
  });

  return (
    <div className="todo-container">
      <div className="todo-card">
        <header className="todo-header">
          <h1 className="todo-title">やることリスト</h1>
          <p className="todo-subtitle">日々のタスクをすっきり整理・完了させましょう</p>
        </header>

        <section className="progress-container">
          <div
            className="progress-bar-bg"
            role="progressbar"
            aria-valuenow={progressPercent}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-label="タスク完了の進捗状況"
          >
            <div
              className="progress-bar-fill"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
          <div className="progress-text">
            <span>進捗率: {progressPercent}%</span>
            <span>
              完了 {completedCount} 件 / 全体 {totalCount} 件
            </span>
          </div>
        </section>

        <form className="todo-form" onSubmit={handleAddTask}>
          <input
            type="text"
            className="todo-input"
            placeholder="新しいタスクを入力してください..."
            value={inputTitle}
            onChange={(e) => setInputTitle(e.target.value)}
          />
          <button
            type="submit"
            className="add-button"
            disabled={!inputTitle.trim()}
          >
            追加する
          </button>
        </form>

        <nav className="filter-tabs" aria-label="タスク絞り込み">
          <button
            type="button"
            className={
              filter === 'all'
                ? 'filter-button filter-button-active'
                : 'filter-button'
            }
            onClick={() => setFilter('all')}
          >
            すべて ({totalCount})
          </button>
          <button
            type="button"
            className={
              filter === 'active'
                ? 'filter-button filter-button-active'
                : 'filter-button'
            }
            onClick={() => setFilter('active')}
          >
            未完了 ({activeCount})
          </button>
          <button
            type="button"
            className={
              filter === 'completed'
                ? 'filter-button filter-button-active'
                : 'filter-button'
            }
            onClick={() => setFilter('completed')}
          >
            完了済み ({completedCount})
          </button>
        </nav>

        {filteredTasks.length === 0 ? (
          <div className="empty-state">
            {filter === 'all' && 'タスクが登録されていません。新しいタスクを追加してみましょう！'}
            {filter === 'active' && '現在、未完了のタスクはありません。素晴らしい！'}
            {filter === 'completed' && '完了済みのタスクはまだありません。'}
          </div>
        ) : (
          <ul className="task-list">
            {filteredTasks.map((task) => (
              <TaskItem
                key={task.id}
                task={task}
                onToggle={handleToggle}
                onDelete={handleDelete}
              />
            ))}
          </ul>
        )}

        <footer className="stats-footer">
          <span>残り {activeCount} 件のタスク</span>
          <button
            type="button"
            className="clear-completed-button"
            onClick={handleClearCompleted}
            disabled={completedCount === 0}
          >
            完了済みをすべて削除 ({completedCount})
          </button>
        </footer>
      </div>
    </div>
  );
};

export default App;
